# Instructions ----
#' This file follows the format generated by FIMS:::use_testthat_template().
#' Necessary tests include input and output (IO) correctness [IO
#' correctness], edge-case handling [Edge handling], and built-in errors and
#' warnings [Error handling]. See `?FIMS:::use_testthat_template` for more
#' information. Every test should have a @description tag, which can only span
#' one lines, that will be used in the bookdown report of the results from
#' {testthat}. This line can be more than 80 characters.

# fit_fims ----
## Setup ----
# 10 years of data_big keep the fits fast. Weight at age has 1 more year, for
# the start of the year after the last model year.
data_10_years <- FIMS::data_big |>
  dplyr::filter(
    is.na(timing) |
      timing <= dplyr::if_else(type == "weight_at_age", 11, 10)
  ) |>
  FIMSFrame()
default_parameters <- setup_default_parameters(data_10_years)

# fleet1's log_Fmort in 2 time blocks, years 1 to 2 and years 3 to 10, so 10
# values share 2 estimates.
blocked_fit <- default_parameters |>
  add_process(
    log_Fmort ~ cut(year, c(-Inf, 2, Inf)),
    module_name = "Fleet",
    fleet = "fleet1"
  ) |>
  initialize_fims(data = data_10_years) |>
  fit_fims()
blocked_estimates <- get_estimates(blocked_fit)

# Every value held constant. The recruitment deviations have no process
# distribution, because a process needs an estimated value to score.
all_constant_input <- default_parameters |>
  dplyr::filter(module_name != "Recruitment") |>
  dplyr::bind_rows(
    setup_default_Recruitment(
      data = data_10_years,
      distribution = NA_character_
    )
  ) |>
  dplyr::mutate(
    estimation_type = dplyr::if_else(
      estimation_type %in% c("fixed_effects", "random_effects"),
      "constant",
      estimation_type
    )
  ) |>
  initialize_fims(data = data_10_years)

## IO correctness ----
test_that("`fit_fims()` gives values that share a map_group 1 estimate", {
  fleet1_log_fmort <- blocked_estimates |>
    dplyr::filter(
      module_name == "Fleet",
      fleet == "fleet1",
      label == "log_Fmort"
    )
  #' @description Test that `fit_fims()` gives every year in a time block from `add_process()` the same estimate.
  expect_equal(
    object = fleet1_log_fmort[["estimated"]],
    expected = rep(fleet1_log_fmort[["estimated"]][c(1, 3)], c(2, 8))
  )
  #' @description Test that `fit_fims()` gives every year in a time block from `add_process()` the same standard error.
  expect_equal(
    object = fleet1_log_fmort[["uncertainty"]],
    expected = rep(fleet1_log_fmort[["uncertainty"]][c(1, 3)], c(2, 8))
  )
  #' @description Test that `fit_fims()` gives the shared estimates of a time block finite standard errors.
  expect_true(all(is.finite(fleet1_log_fmort[["uncertainty"]])))
  #' @description Test that `fit_fims()` reports the gradient of a shared estimate only on the first year of its time block.
  expect_equal(
    object = is.na(fleet1_log_fmort[["gradient"]]),
    expected = !(seq_len(10) %in% c(1, 3))
  )
  unblocked_fit <- default_parameters |>
    initialize_fims(data = data_10_years) |>
    fit_fims(optimize = FALSE)
  #' @description Test that `fit_fims()` counts 2 fixed effects, not 10, for 10 years of log_Fmort in 2 time blocks.
  expect_equal(
    object = get_number_of_parameters(blocked_fit)[["fixed_effects"]],
    expected = get_number_of_parameters(unblocked_fit)[["fixed_effects"]] - 8
  )
})

test_that("`fit_fims()` holds constant values at their starting values", {
  constant_rows <- blocked_estimates |>
    dplyr::filter(estimation_type == "constant")
  #' @description Test that `fit_fims()` gives every constant value an NA standard error.
  expect_true(all(is.na(constant_rows[["uncertainty"]])))
  #' @description Test that `fit_fims()` keeps every constant value at its starting value.
  expect_equal(
    object = constant_rows[["estimated"]],
    expected = constant_rows[["input"]]
  )
})

## Edge handling ----
test_that("`fit_fims()` returns correct outputs for edge cases", {
  random_effects_only_fit <- default_parameters |>
    dplyr::mutate(
      estimation_type = dplyr::if_else(
        estimation_type == "fixed_effects",
        "constant",
        estimation_type
      )
    ) |>
    initialize_fims(data = data_10_years) |>
    fit_fims()
  random_effects <- get_estimates(random_effects_only_fit) |>
    dplyr::filter(estimation_type == "random_effects")
  #' @description Test that `fit_fims()` with every fixed effect constant counts 0 fixed effects and 9 random effects, the recruitment deviations in years 2 to 10.
  expect_equal(
    object = get_number_of_parameters(random_effects_only_fit),
    expected = c(fixed_effects = 0, random_effects = 9)
  )
  #' @description Test that `fit_fims()` with every fixed effect constant evaluates the model without an outer optimizer.
  expect_equal(
    object = get_opt(random_effects_only_fit)[["message"]],
    expected = "No fixed effects to optimize"
  )
  #' @description Test that `fit_fims()` with every fixed effect constant reports a maximum gradient of 0.
  expect_equal(
    object = get_max_gradient(random_effects_only_fit),
    expected = 0
  )
  #' @description Test that `fit_fims()` with every fixed effect constant still estimates the random effects, which move from their starting values of 0.
  expect_true(all(random_effects[["estimated"]] != random_effects[["input"]]))
  #' @description Test that `fit_fims()` with every fixed effect constant gives the random effects finite standard errors.
  expect_true(all(is.finite(random_effects[["uncertainty"]])))

  all_constant_fit <- fit_fims(all_constant_input, optimize = FALSE)
  #' @description Test that `fit_fims(optimize = FALSE)` with every value constant counts 0 fixed effects and 0 random effects.
  expect_equal(
    object = get_number_of_parameters(all_constant_fit),
    expected = c(fixed_effects = 0, random_effects = 0)
  )
  #' @description Test that `fit_fims(optimize = FALSE)` with every value constant gives every row an NA standard error.
  expect_true(all(is.na(get_estimates(all_constant_fit)[["uncertainty"]])))
})

## Error handling ----
test_that("`fit_fims()` returns correct error messages", {
  #' @description Test that `fit_fims()` errors when every value is constant and `optimize = TRUE`.
  expect_error(
    object = fit_fims(all_constant_input),
    regexp = "at least one parameter to optimize"
  )
  p_map_input <- initialize_fims(default_parameters, data = data_10_years)
  p_map_input[["map"]] <- list(p = factor(1))
  #' @description Test that `fit_fims()` errors with a pointer to `map_group` when `input$map` names something that is not a model parameter, such as `p`.
  expect_error(
    object = fit_fims(p_map_input, optimize = FALSE),
    regexp = "map_group"
  )
})
